window.RTLBenchLSData.register("assets/d3451d67a07a9f81919fe37d6f450152b65db6945b49b45164d72f7f9e77b1ad.txt","module mg_06064 (parity_out, data_in);\nparameter WIDTH = 8 ; \n parameter NUM = 16 ; \n input [WIDTH * NUM - 1 : 0] data_in ; \n output [NUM - 1 : 0] parity_out ; \n reg [NUM - 1 : 0] parity ; \n integer i ; \n integer j ; \n always @(data_in) \n  for (i = 0; i <= NUM - 1 ; i = i + 1) begin \n  parity[i] = 1'b0 ; \n  for (j = WIDTH * i; j <= WIDTH * (i + 1) - 1 ; j = j + 1) begin \n  parity[i] = parity[i] ^ data_in[j] ; \n  end \n  end \n assign parity_out[NUM - 1 : 0] = parity[NUM - 1 : 0]; \n endmodule");
